def solve_sequence():
    # a[n] stores a_n. Use 1-based indexing conceptually, so list size N+1.
    a = {1: 0}

    for n in range(2, 11):
        max_val = -float('inf')
        i_max_candidates = []

        for i in range(1, n):
            # E_i = a_i + a_{n - i} + min(i, n - i)
            E_i = a[i] + a[n - i] + min(i, n - i)

            if E_i > max_val:
                max_val = E_i
                i_max_candidates = [i]
            elif E_i == max_val:
                i_max_candidates.append(i)

        a[n] = max_val

        print(f"n={n}, a_{n}={a[n]}, i_max_candidates={i_max_candidates}")

    return a

a_values = solve_sequence()
print("\nFinal values of a_n up to n=10:", a_values)
